mapper.select:
SELECT COUNT(*)
  FROM TB_REVIEW
 WHERE REVIEW_TYPE = 'HOSPITAL'
   AND RESV_ID = #{resvId}
   AND MEMBER_NO = #{memberNo}

mapper.update:
UPDATE TB_HOSPITAL H
   SET AVG_RATING = (
         SELECT ROUND(AVG(R.RATING), 1)
           FROM TB_REVIEW R
          WHERE R.REVIEW_TYPE = 'HOSPITAL'
            AND R.TARGET_ID = #{hospitalId}
       ),
       REVIEW_CNT = (
         SELECT COUNT(*)
           FROM TB_REVIEW R
          WHERE R.REVIEW_TYPE = 'HOSPITAL'
            AND R.TARGET_ID = #{hospitalId}
       )
 WHERE H.HOSPITAL_ID = #{hospitalId}

UPDATE TB_STAY S
   SET AVG_RATING = (
         SELECT ROUND(AVG(R.RATING), 1)
           FROM TB_REVIEW R
          WHERE R.REVIEW_TYPE = 'STAY'
            AND R.TARGET_ID = #{stayId}
       ),
       REVIEW_CNT = (
         SELECT COUNT(*)
           FROM TB_REVIEW R
          WHERE R.REVIEW_TYPE = 'STAY'
            AND R.TARGET_ID = #{stayId}
       )
 WHERE S.STAY_ID = #{stayId}

